      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = t === 'dark' ? '🌙' : '☀️';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // Download PNG
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      if (menu) menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2 });
        var a = document.createElement('a'); a.href = url;
        a.download = 'global-education-poster.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      if (menu) menu.style.display = '';
    }

    // Number Counter
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
          else el.textContent = prefix + target.toLocaleString() + suffix;
        })(start);
      });
    }
    setTimeout(animateCounters, 300);

    // Chart.js
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') return null;
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) return null;
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) {
          console.error('Chart init failed:', error);
          return null;
        }
      }
    };

    function buildCharts() {
      var s = getComputedStyle(document.documentElement);
      var colors = {
        text: s.getPropertyValue('--text').trim(),
        textSec: s.getPropertyValue('--text-secondary').trim(),
        border: s.getPropertyValue('--border').trim(),
        accent: s.getPropertyValue('--accent').trim(),
        negative: s.getPropertyValue('--negative').trim()
      };

      ChartManager.safeInit('dropoutChart', {
        type: 'doughnut',
        data: {
          labels: ['Primary-age', 'Secondary-age'],
          datasets: [{
            data: [60, 184],
            backgroundColor: [colors.accent, colors.negative],
            borderWidth: 0
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false, animation: false,
          plugins: {
            tooltip: { enabled: true, padding: 16, titleFont: { size: 16 }, bodyFont: { size: 16 } },
            legend: { position: 'bottom', labels: { color: colors.text, padding: 24, font: { family: 'Inter', size: 16 } } }
          },
          cutout: '70%',
          layout: { padding: 20 }
        }
      });
    }

    function onThemeChange() { setTimeout(buildCharts, 100); }
    document.addEventListener('DOMContentLoaded', buildCharts);
  </script>
</body>
</html>
